test("PWA contract: app registers its service worker", () => {
  const match = html.match(/navigator\.serviceWorker\.register\(\s*["']([^"']+)["']/);
  assert.ok(match, "app must call navigator.serviceWorker.register() with a script path");
  assert.ok(match[1].endsWith(".js"), "registered service worker path must be a JavaScript file");
  const workerPath = path.resolve(__dirname, match[1]);
  assert.ok(workerPath.startsWith(`${__dirname}${path.sep}`), "service worker must be local to the app repository");
  assert.ok(fs.existsSync(workerPath), `registered service worker source must exist: ${match[1]}`);
});

test("PWA contract: service worker precaches the app and uses a cache-first fetch strategy", () => {
  const match = html.match(/navigator\.serviceWorker\.register\(\s*["']([^"']+)["']/);
  assert.ok(match, "service-worker source path must be discoverable from the app registration");
  const workerPath = path.resolve(__dirname, match[1]);
  assert.ok(fs.existsSync(workerPath), `service-worker source must exist: ${match[1]}`);
  const worker = fs.readFileSync(workerPath, "utf8");

  assert.match(worker, /addEventListener\(\s*["']install["']/,
    "service worker must install a cache");
  assert.match(worker, /caches\.open\(/, "service worker must open a named cache");
  assert.match(worker, /\.addAll\(\s*\[/, "service worker must precache the app shell");
  assert.match(worker, /addEventListener\(\s*["']fetch["']/,
    "service worker must handle fetches");
  assert.match(worker, /event\.respondWith\(/,
    "fetch handling must control the response with event.respondWith()");
  assert.match(worker, /caches\.match\(/, "fetch handling must check the cache first");
  assert.match(worker, /caches\.match\(\s*event\.request\s*\)[\s\S]{0,240}\|\|\s*fetch\(\s*event\.request\s*\)/,
    "fetch handling must return the cached response before falling back to the network request");
  assert.match(worker, /addEventListener\(\s*["']activate["']/,
    "service worker must activate and retire old shell caches");
  assert.match(worker, /clients\.claim\(\)/, "service worker must claim already-open app clients");
  assert.match(worker, /caches\.match\(\s*["']\.\/index\.html["']\s*\)/,
    "failed navigations must fall back to the cached app shell");
});

function serviceWorkerSource() {
  const match = html.match(/navigator\.serviceWorker\.register\(\s*["']([^"']+)["']/);
  assert.ok(match, "service-worker source path must be discoverable from the app registration");
  const workerPath = path.resolve(__dirname, match[1]);
  assert.ok(workerPath.startsWith(`${__dirname}${path.sep}`), "service worker must stay inside the app repository");
  return fs.readFileSync(workerPath, "utf8");
}

function appShellContract(worker) {
  const cacheMatch = worker.match(/const\s+CACHE_NAME\s*=\s*["']([^"']+)["']/);
  assert.ok(cacheMatch, "service worker must declare a literal CACHE_NAME");

  const addAllMatch = worker.match(/\.addAll\(\s*\[([\s\S]*?)\]/);
  assert.ok(addAllMatch, "service worker must precache a literal app-shell path list");
  const rawPaths = [...addAllMatch[1].matchAll(/["']([^"']+)["']/g)].map((match) => match[1]);
  assert.ok(rawPaths.length > 0, "service worker app-shell path list must not be empty");

  const localPaths = [...new Set(rawPaths.flatMap((entry) => {
    // Remote URLs are intentionally not part of the local shell fingerprint.
    if (/^(?:[a-z][a-z\d+.-]*:)?\/\//i.test(entry) || /^[a-z][a-z\d+.-]*:/i.test(entry)) return [];
    const normalized = path.posix.normalize(entry.replace(/^\.\//, ""));
    // The root navigation and its explicit HTML fallback are the same shell file.
    if (normalized === "." || normalized === "index.html") return ["index.html"];
    // A worker cannot fingerprint itself without creating a circular release key.
    if (normalized === "sw.js") return [];
    return [normalized];
  }))].sort();
  assert.ok(localPaths.includes("index.html"), "app-shell fingerprint must include index.html");

  const hash = createHash("sha256");
  for (const relativePath of localPaths) {
    const absolutePath = path.resolve(__dirname, relativePath);
    assert.ok(absolutePath.startsWith(`${__dirname}${path.sep}`),
      `precached local asset must stay inside the app repository: ${relativePath}`);
    assert.ok(fs.existsSync(absolutePath), `precached local asset must exist: ${relativePath}`);
    hash.update(relativePath);
    hash.update("\0");
    hash.update(fs.readFileSync(absolutePath));
    hash.update("\0");
  }

  return {
    cacheName: cacheMatch[1],
    rawPaths,
    localPaths,
    fingerprint: hash.digest("hex"),
  };
}

test("PWA cache contract: CACHE_NAME is mechanically tied to every local app-shell byte", () => {
  const { cacheName, fingerprint } = appShellContract(serviceWorkerSource());
  assert.equal(cacheName, `chain-scanner-shell-${fingerprint}`,
    "changing any locally precached shell asset must require a corresponding cache-key update");
});

function serviceWorkerHarness(worker, existingCacheNames = []) {
  const handlers = {};
  const cacheRecords = new Map(existingCacheNames.map((name) => [name, { added: [] }]));
  let skipWaitingCalls = 0;
  let claimCalls = 0;
  const caches = {
    open(name) {
      if (!cacheRecords.has(name)) cacheRecords.set(name, { added: [] });
      const record = cacheRecords.get(name);
      return Promise.resolve({
        addAll(entries) {
          record.added.push(...entries);
          return Promise.resolve();
        },
        put() { return Promise.resolve(); },
      });
    },
    keys() { return Promise.resolve([...cacheRecords.keys()]); },
    delete(name) { return Promise.resolve(cacheRecords.delete(name)); },
    match() { return Promise.resolve(undefined); },
  };
  const context = {
    caches,
    console,
    fetch() { return Promise.reject(new Error("network should not be used in lifecycle test")); },
    URL,
    Request: class { constructor(url, options){ this.url=url; this.cache=options.cache; } },
    self: {
      location: { origin: "https://scanner.example" },
      addEventListener(type, handler) { handlers[type] = handler; },
      skipWaiting() { skipWaitingCalls += 1; return Promise.resolve(); },
      clients: { claim() { claimCalls += 1; return Promise.resolve(); } },
    },
  };
  vm.runInNewContext(worker, context, { filename: "sw.js" });
  return { handlers, cacheRecords, skipWaitingCalls: () => skipWaitingCalls, claimCalls: () => claimCalls };
}

test("PWA lifecycle: current shell installs and activation retires prior shell caches", async () => {
  const worker = serviceWorkerSource();
  const { cacheName, rawPaths } = appShellContract(worker);
  const harness = serviceWorkerHarness(worker, ["chain-scanner-shell-v1", "unrelated-cache"]);

  const installWaits = [];
  harness.handlers.install({ waitUntil(promise) { installWaits.push(promise); } });
  await Promise.all(installWaits);
  assert.deepEqual(harness.cacheRecords.get(cacheName).added.map(request=>request.url), rawPaths,
    "install must precache the exact current app-shell path list");
  assert.equal(harness.skipWaitingCalls(), 1, "install must activate the new worker immediately");

  const activateWaits = [];
  harness.handlers.activate({ waitUntil(promise) { activateWaits.push(promise); } });
  await Promise.all(activateWaits);
  assert.equal(harness.cacheRecords.has("chain-scanner-shell-v1"), false,
    "activation must delete the previous shell cache");
  assert.equal(harness.cacheRecords.has(cacheName), true,
    "activation must retain the current fingerprinted shell cache");
  assert.equal(harness.cacheRecords.has("unrelated-cache"), true,
    "activation must leave unrelated caches alone");
  assert.equal(harness.claimCalls(), 1, "activation must claim already-open app clients");
});

function slice(src, startMarker, endMarker) {
  const s = src.indexOf(startMarker);
  const e = src.indexOf(endMarker);
  if (s === -1 || e === -1 || e < s) throw new Error(`markers not found: ${startMarker} .. ${endMarker}`);
  return src.slice(s + startMarker.length, e);
}
const engineSrc = slice(html, "/*ENGINE-START*/", "/*ENGINE-END*/");

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SEED_SNIPPET = (seed) => `
Math.random = (function(seed){
  let a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
})(${seed});
`;

function loadEngine(seed) {
  const sandbox = {};
  vm.createContext(sandbox);
  // Seed FIRST, inside the context — vm contexts don't expose their built-in
  // Math as a settable property on the outer sandbox object, so reassigning
  // Math.random has to happen as code run *in* the context, not from outside.
  if (seed !== undefined) vm.runInContext(SEED_SNIPPET(seed), sandbox);
  vm.runInContext(engineSrc, sandbox, { filename: "index.html#engine" });
  return sandbox;
}
// `const`/`let` at top level (SIGMA_FLOOR, BETA, TAU, ...) live in the script's
// lexical scope, not as properties of the sandbox object — unlike `function`
// declarations, which do attach. Read them by evaluating the bare name inside
// the same context instead of via the returned object.
function readConst(sandbox, name) {
  return vm.runInContext(name, sandbox);
}

/* =====================================================================
   Harness for the FULL app script (state, decide/*, addTask, deleteTask,
   parseTaskList, the new queue-gate, etc.) — the classic (non-module)
   <script> block, identified by its "use strict" opener so it doesn't
   depend on script ordering in the file.
   ===================================================================== */
function extractAppScript(src) {
  const m = src.match(/<script>\s*"use strict";([\s\S]*?)<\/script>/);
  if (!m) throw new Error("could not find the main app <script> block");
  return '"use strict";' + m[1];
}
const appSrc = extractAppScript(html);

function makeFakeElement() {
  const el = {
    innerHTML: "", textContent: "", value: "", hidden: false, scrollTop: 0, children: [],
    dataset: {}, style: {},
    classList: {
      _set: new Set(),
      toggle(cls, force) {
        if (force === undefined) { this._set.has(cls) ? this._set.delete(cls) : this._set.add(cls); }
        else if (force) { this._set.add(cls); } else { this._set.delete(cls); }
      },
      add(cls) { this._set.add(cls); },
      remove(cls) { this._set.delete(cls); },
      contains(cls) { return this._set.has(cls); },
    },
    addEventListener() {}, removeEventListener() {},
    focus() {}, select() {}, click() {},
    querySelector() { return null; }, querySelectorAll() { return []; },
    // Attributes are really stored now (they used to be no-op stubs) so that
    // <html data-theme="..."> can be asserted on. getAttribute still returns
    // null for anything never set, which is what the old stub always did.
    _attrs: new Map(),
    getAttribute(k) { return this._attrs.has(k) ? this._attrs.get(k) : null; },
    setAttribute(k, v) { this._attrs.set(k, String(v)); },
    removeAttribute(k) { this._attrs.delete(k); },
    hasAttribute(k) { return this._attrs.has(k); },
    appendChild(child) { this.children.push(child); }, append(child) { this.children.push(child); }, scrollIntoView() {},
  };
  return el;
}

function makeDomShim({ prefersDark = false, sharedStorage = null } = {}) {
  const elements = new Map();
  const winListeners = {};
  const documentListeners = {};
  const localStorageMap = new Map();

  const documentElement = makeFakeElement();

  const document = {
    getElementById(id) {
      if (!elements.has(id)) elements.set(id, makeFakeElement());
      return elements.get(id);
    },
    querySelector() { return null; },   // "no modal open" by default
    querySelectorAll() { return []; },
    addEventListener(evt, fn) { (documentListeners[evt] ||= []).push(fn); },
    removeEventListener() {},
    dispatchEvent(evt) {
      for (const fn of (documentListeners[evt.type] || [])) fn(evt);
      return true;
    },
    createElement() { return makeFakeElement(); },
    body: { appendChild() {} },
    documentElement,
  };
  const localStorage = sharedStorage || {
    getItem(k) { return localStorageMap.has(k) ? localStorageMap.get(k) : null; },
    setItem(k, v) { localStorageMap.set(k, String(v)); },
    removeItem(k) { localStorageMap.delete(k); },
  };
  // A minimal MediaQueryList good enough for prefers-color-scheme. `setDark`
  // flips the OS preference and notifies listeners the way a real browser does
  // when you change the system appearance while the page is open.
  const mqlListeners = [];
  const mql = {
    media: "(prefers-color-scheme: dark)",
    matches: prefersDark,
    addEventListener(evt, fn) { if (evt === "change") mqlListeners.push(fn); },
    removeEventListener(evt, fn) {
      const i = mqlListeners.indexOf(fn);
      if (i >= 0) mqlListeners.splice(i, 1);
    },
  };
  function setDark(v) {
    mql.matches = !!v;
    for (const fn of [...mqlListeners]) fn({ matches: mql.matches, media: mql.media });
  }

  const window = {
    addEventListener(evt, fn) { (winListeners[evt] ||= []).push(fn); },
    removeEventListener() {},
    dispatchEvent(evt) {
      for (const fn of (winListeners[evt.type] || [])) fn(evt);
      return true;
    },
    matchMedia(q) {
      // Only the color-scheme query is modelled; anything else reports no match.
      if (String(q).includes("prefers-color-scheme: dark")) return mql;
      return { media: String(q), matches: false, addEventListener() {}, removeEventListener() {} };
    },
    localStorage,
    CloudSync: undefined,
  };
  window.window = window;
  return { document, window, localStorage, elements, winListeners, documentElement, setDark, mqlListeners };
}

const flush = () => new Promise((r) => setTimeout(r, 0));

async function loadApp({ seed, cloudSyncFactory, prefersDark = false, noMatchMedia = false, seedStorage, sharedStorage, hostStorage, hostStorageDelayMs = 0, beforeStateReady, cryptoProvider = webcrypto, indexedDBProvider, deviceDbName, deviceOpenTimeoutMs, withSceneModules = false, sceneModulesAfterDomReady = false } = {}) {
  const shim = makeDomShim({ prefersDark, sharedStorage });
  if (noMatchMedia) delete shim.window.matchMedia;   // old browser / bare JS host
  if (seedStorage) for (const [k, v] of Object.entries(seedStorage)) shim.localStorage.setItem(k, v);
  /* The OTHER persistence backend. loadState() prefers window.storage (the
     artifact host's async key-value store) and only falls back to
     localStorage — `useLocal` — when there isn't one. Every existing test
     runs the localStorage path; pass hostStorage to run the other. */
  if (hostStorage) {
    const map = new Map(Object.entries(hostStorage));
    shim.window.storage = {
      _map: map,
      async get(k) {
        if (hostStorageDelayMs) await new Promise((resolve) => setTimeout(resolve, hostStorageDelayMs));
        return map.has(k) ? { value: map.get(k) } : null;
      },
      async set(k, v) { map.set(k, String(v)); },
    };
  }
  if (cloudSyncFactory) shim.window.CloudSync = cloudSyncFactory(shim.window);
  if (deviceDbName) shim.window.CHAIN_STORAGE_DB_NAME = deviceDbName;
  if (deviceOpenTimeoutMs) shim.window.CHAIN_STORAGE_OPEN_TIMEOUT_MS = deviceOpenTimeoutMs;
  if (indexedDBProvider) shim.window.indexedDB = indexedDBProvider;
  const sandbox = {
    window: shim.window,
    document: shim.document,
    localStorage: shim.localStorage,
    console,
    JSON,
    crypto:cryptoProvider,
    indexedDB:indexedDBProvider,
    TextEncoder,
    TextDecoder,
    structuredClone,
    // NOTE: deliberately NOT injecting the outer process's `Date` here — it's
    // passed by reference, so overriding Date.now on it (for time-travel
    // tests) would leak into the whole Node process. Leave Date unset and the
    // vm context auto-provisions its own separate, safely-overridable Date;
    // see setFakeTime() below, which overrides it via in-context code only.
    CustomEvent: class CustomEvent { constructor(type, opts) { this.type = type; Object.assign(this, opts || {}); } },
    setTimeout: (fn, ms, ...a) => { const t = setTimeout(fn, ms, ...a); t.unref?.(); return t; },
    clearTimeout,
    requestAnimationFrame: (fn) => setTimeout(fn, 0),
    confirm: () => true,
    alert: () => {},
    prompt: () => null,
  };
  vm.createContext(sandbox);
  vm.runInContext(lzStringSrc, sandbox, { filename: "vendor/lz-string-1.5.0.min.js" });
  if(indexedDBProvider){
    vm.runInContext(fs.readFileSync(path.join(__dirname,"device-store-v2.js"),"utf8"),sandbox,{filename:"device-store-v2.js"});
    vm.runInContext(fs.readFileSync(path.join(__dirname,"cloud-store-v2.js"),"utf8"),sandbox,{filename:"cloud-store-v2.js"});
    shim.window.ChainStorageV2=sandbox.ChainStorageV2;
    shim.window.ChainCloudV2=sandbox.ChainCloudV2;
  }
  if (seed !== undefined) vm.runInContext(SEED_SNIPPET(seed), sandbox);
  const installSceneModules = () => {
    vm.runInContext(fs.readFileSync(path.join(__dirname, "location.js"), "utf8"), sandbox, { filename: "location.js" });
    const timeKey = "fvp:chain-scanner:scene-time", seasonKey = "fvp:chain-scanner:scene-season";
    sandbox.LivingSky = {
      readSceneTime: storage => storage.getItem(timeKey),
      readSceneSeason: storage => storage.getItem(seasonKey),
    };
    return () => { shim.window.applySyncedSceneTime = (time, season) => {
      if (time === null) shim.localStorage.removeItem(timeKey);
      else shim.localStorage.setItem(timeKey, time);
      if (season === null) shim.localStorage.removeItem(seasonKey);
      else shim.localStorage.setItem(seasonKey, season);
    }; };
  };
  if (withSceneModules && !sceneModulesAfterDomReady) installSceneModules()();
  if (sceneModulesAfterDomReady) shim.document.readyState = "loading";
  vm.runInContext(appSrc, sandbox, { filename: "index.html#app" });
  beforeStateReady?.(sandbox, shim);
  if (sceneModulesAfterDomReady) {
    await flush(); // the inline boot script can resume before deferred modules execute
    const installTimeHook=installSceneModules();
    shim.document.readyState = "interactive";
    shim.document.dispatchEvent({ type: "DOMContentLoaded" });
    await flush(); // landscape.js also awaits its local spawn-rates file
    installTimeHook();
    shim.document.dispatchEvent({ type: "landscape-scene-time-ready" });
  }
  // `state` is a top-level `let`, reassigned wholesale by undo()/cloudPull() —
  // expose it as a live getter (re-reading the binding each time) rather than
  // a one-time snapshot, so it never goes stale after such a reassignment.
  Object.defineProperty(sandbox, "state", {
    get() { return vm.runInContext("state", sandbox); },
    configurable: true,
  });
  // `esc` is a top-level `const` arrow fn (not `function esc(){}`), so — like
  // SIGMA_FLOOR and state — it never attaches to the sandbox object on its
  // own. It's never reassigned though, so a one-time copy is fine here.
  vm.runInContext("this.esc = esc;", sandbox);
  await flush(); // let the boot IIFE's `await loadState()` resolve before returning
  if(indexedDBProvider){
    // Hashing and IndexedDB completion are not bounded by an event-loop count.
    // Await readiness with an explicit deadline so slowness cannot masquerade
    // as an unrelated task-action failure against null state.
    const deadline=Date.now()+5000;
    while(vm.runInContext("state",sandbox)===null && Date.now()<deadline) await flush();
    assert.notEqual(vm.runInContext("state",sandbox),null,"App durable startup did not finish within 5 seconds");
  }
  return { ctx: sandbox, shim };
}

// Overrides Date.now() *inside one vm context only*, via in-context code —
// never touches the outer process's real Date, so it can't leak across tests.
function setFakeTime(sandbox, ts) {
  vm.runInContext(`Date.now = () => ${ts};`, sandbox);
}
function realNow(sandbox) {
  return vm.runInContext("Date.now()", sandbox);
}

test("app harness: boots cleanly with an empty state", async () => {
  const { ctx } = await loadApp();
  assert.ok(ctx.state, "state should be initialized after boot");
  assert.equal(ctx.state.tasks.length, 0);
  assert.equal(ctx.state.chain.length, 0);
  assert.equal(ctx.state.mode, "scan");
});

/* ---------- state mutations ---------- */

test("addTask: adds an open task; dot=true also pushes it onto the chain", async () => {
  const { ctx } = await loadApp();
  const t1 = ctx.addTask("Write scene", false);
  assert.equal(ctx.state.tasks.length, 1);
  assert.equal(t1.title, "Write scene");
  assert.equal(ctx.state.chain.length, 0);

  const t2 = ctx.addTask("Urgent fix", true);
  assert.equal(ctx.state.tasks.length, 2);
  assert.equal(ctx.state.chain.length, 1);
  assert.equal(ctx.state.chain[0], t2.id);
});

test("addTask: blank/whitespace-only titles are rejected", async () => {
  const { ctx } = await loadApp();
  assert.equal(ctx.addTask("   ", false), null);
  assert.equal(ctx.state.tasks.length, 0);
});

test("addTask: new tasks default startsAt to null", async () => {
  const { ctx } = await loadApp();
  const t = ctx.addTask("Task A", false);
  assert.equal(ctx.state.tasks.find((x) => x.id === t.id).startsAt, null);
});

test("importList: new tasks default startsAt to null", async () => {
  const { ctx } = await loadApp();
  ctx.importList("1. Task A");
  assert.equal(ctx.state.tasks[0].startsAt, null);
});

test("decide('yes'): dots the candidate, clears it, and a new candidate is picked from the remaining pool", async () => {
  const { ctx } = await loadApp({ seed: 1 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.addTask("Task C", false);
  ctx.startScan('descending');              // dots Task A; yes/no need a benchmark to compare against
  const firstCandidate = ctx.state.candidateId;
  assert.ok(firstCandidate, "a ranked candidate should be presented once the chain has started");

  ctx.decide("yes");
  assert.equal(ctx.state.chain.length, 2);
  assert.equal(ctx.state.chain[1], firstCandidate, "the dotted task should be the one that was showing");
  assert.notEqual(ctx.state.candidateId, firstCandidate, "a fresh candidate should replace the dotted one");
  assert.ok(ctx.state.candidateId, "a new candidate should be offered (1 task remains in the pool)");
});

test("decide('no') and decide('cant'): candidate is marked considered, NOT added to the chain", async () => {
  const { ctx } = await loadApp({ seed: 2 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.addTask("Task C", false);
  ctx.startScan('descending');              // establish a benchmark so 'no' is a valid comparison
  const chainLen = ctx.state.chain.length;
  const cand = ctx.state.candidateId;
  ctx.decide("no");
  assert.equal(ctx.state.chain.length, chainLen, "'no' must not extend the chain");
  assert.equal(ctx.state.considered[cand], "no");
});

test("decide('cand-done'): completes the task directly without ever touching the chain", async () => {
  const { ctx } = await loadApp({ seed: 3 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');              // dots Task A, so Task B comes up as the candidate
  const cand = ctx.state.candidateId;
  ctx.decide("cand-done");
  const task = ctx.state.tasks.find((t) => t.id === cand);
  assert.equal(task.done, true);
  assert.ok(!ctx.state.chain.includes(cand), "cand-done must not add the task to the chain");
  assert.equal(ctx.state.chain.length, 1, "the task dotted at the start is the only thing on it");
});

/* Done records completion without adding preference evidence. */

test("decide('cand-done'): completing the candidate leaves both ratings alone", async () => {
  const { ctx } = await loadApp({ seed: 3 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');                       // dots Task A; Task B is the candidate
  const candId = ctx.state.candidateId;
  const benchId = ctx.state.chain[ctx.state.chain.length - 1];
  const cand = ctx.state.tasks.find((t) => t.id === candId);
  const bench = ctx.state.tasks.find((t) => t.id === benchId);
  const snap = { cm: cand.mu, cs: cand.sigma, bm: bench.mu, bs: bench.sigma };

  ctx.decide("cand-done");

  assert.equal(cand.mu, snap.cm);
  assert.equal(cand.sigma, snap.cs);
  assert.equal(bench.mu, snap.bm, "benchmark mu must be untouched");
  assert.equal(bench.sigma, snap.bs, "benchmark sigma must be untouched");
  assert.equal(cand.done, true, "and the task is still completed");
});

test("decide('cand-done'): an evergreen candidate stays rating-neutral and still logs its completion", async () => {
  const { ctx } = await loadApp({ seed: 7 });
  ctx.addTask("Task A", false);
  ctx.addTask("Water the plants", false);
  const evergreen = ctx.state.tasks.find((t) => t.title === "Water the plants");
  evergreen.evergreen = true;
  ctx.startScan('descending');                       // dots Task A; the evergreen is the candidate
  const candId = ctx.state.candidateId;
  const benchId = ctx.state.chain[ctx.state.chain.length - 1];
  const cand = ctx.state.tasks.find((t) => t.id === candId);
  const bench = ctx.state.tasks.find((t) => t.id === benchId);
  assert.equal(candId, evergreen.id, "precondition: the evergreen task is the one being weighed");
  const snap = { cm: cand.mu, cs: cand.sigma, bm: bench.mu, bs: bench.sigma };

  ctx.decide("cand-done");

  assert.equal(cand.mu, snap.cm);
  assert.equal(cand.sigma, snap.cs);
  assert.equal(bench.mu, snap.bm, "benchmark mu untouched");
  assert.equal(bench.sigma, snap.bs, "benchmark sigma untouched");
  const logged = ctx.state.workLog.some((e) => e.taskId === candId && e.kind === "evergreen-done");
  assert.ok(logged, "the evergreen completion is still recorded in the work log");
});

/* Guards that the change above is confined to the cand-done branch: yes and no
   still feed the ranker, because those ARE answered comparisons. */

test("decide('yes'): still records the candidate outranking the benchmark", async () => {
  const { ctx } = await loadApp({ seed: 4 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');
  const candId = ctx.state.candidateId;
  const benchId = ctx.state.chain[ctx.state.chain.length - 1];
  const cand = ctx.state.tasks.find((t) => t.id === candId);
  const bench = ctx.state.tasks.find((t) => t.id === benchId);
  const cm = cand.mu, bm = bench.mu;

  ctx.decide("yes");

  assert.ok(cand.mu > cm, "a 'yes' lifts the candidate's mu");
  assert.ok(bench.mu < bm, "and lowers the benchmark's");
});

test("decide('no'): still records the benchmark outranking the candidate", async () => {
  const { ctx } = await loadApp({ seed: 5 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');
  const candId = ctx.state.candidateId;
  const cand = ctx.state.tasks.find((t) => t.id === candId);
  const cm = cand.mu;

  ctx.decide("no");

  assert.ok(cand.mu < cm, "a 'no' lowers the candidate's mu");
});

test("deleteTask: removes from tasks, the chain, and considered; clears candidateId if it was the deleted task", async () => {
  const { ctx } = await loadApp({ seed: 4 });
  const t1 = ctx.addTask("Task A", true); // dotted
  ctx.addTask("Task B", false);
  const cand = ctx.state.candidateId;

  ctx.deleteTask(cand);
  assert.equal(ctx.state.tasks.some((t) => t.id === cand), false);
  assert.notEqual(ctx.state.candidateId, cand);

  ctx.deleteTask(t1.id);
  assert.equal(ctx.state.chain.includes(t1.id), false, "deleting a dotted task must remove it from the chain too");
});

test("deleteTask: a null/undefined id is a safe no-op", async () => {
  const { ctx } = await loadApp();
  ctx.addTask("Task A", false);
  ctx.deleteTask(null);
  ctx.deleteTask(undefined);
  assert.equal(ctx.state.tasks.length, 1);
});

test("undo: reverses the most recent mutation (dotting a task)", async () => {
  const { ctx } = await loadApp({ seed: 5 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');                // dots A; B comes up as the candidate
  assert.equal(ctx.state.chain.length, 1);
  ctx.decide("yes");
  assert.equal(ctx.state.chain.length, 2);
  ctx.undo();
  assert.equal(ctx.state.chain.length, 1);
});

/* ---------- undo has to be durable, not just visible ----------
   undo() restored the snapshot on screen but called commit(false), which skips
   save() — so the reverted state never reached storage. Since save() is
   debounced, any undo more than ~350ms after the action it reverses left the
   pre-undo state on disk, and a reload resurrected whatever you just took back.
   save() also stamps updatedAt, which is what arbitrates the cloud's
   last-write-wins: an undo carrying its snapshot's stale timestamp loses the
   next reconcile to the remote copy it was meant to overrule. */

const SAVE_DEBOUNCE_MS = 350;
const settle = () => new Promise((r) => setTimeout(r, SAVE_DEBOUNCE_MS + 120));
const persisted = (shim) => JSON.parse(shim.localStorage.getItem("fvp:chain-scanner:v1"));

test("undo: writes the restored state to storage, so a reload doesn't resurrect it", async () => {
  const { ctx, shim } = await loadApp({ seed: 40 });
  const t = ctx.addTask("Task A", false);
  ctx.doneTask(t.id);
  await settle();
  assert.deepEqual(persisted(shim).tasks.filter((x) => x.done).map((x) => x.title), ["Task A"],
    "precondition: the completion reached storage before the undo");

  ctx.undo();
  await settle();
  assert.deepEqual(persisted(shim).tasks.filter((x) => x.done), [],
    "the undone completion must not still be on disk");
  assert.equal(persisted(shim).tasks.find((x) => x.id === t.id).done, false);
});

test("undo: a persisted deletion restores its task without the old tombstone deleting it again", async () => {
  const { ctx, shim } = await loadApp({ seed: 400 });
  const t = ctx.addTask("Keep after undo", false);
  await settle();
  ctx.deleteTask(t.id);
  await settle();
  assert.equal(persisted(shim).tasks.some((x) => x.id === t.id), false);
  ctx.undo();
  await settle();
  assert.equal(persisted(shim).tasks.some((x) => x.id === t.id), true);
});

test("undo: stamps updatedAt so the restored state outranks the copy it reverses", async () => {
  const { ctx } = await loadApp({ seed: 41 });
  ctx.addTask("Task A", false);
  ctx.addTask("Task B", false);
  ctx.startScan('descending');
  const stale = ctx.state.updatedAt;
  ctx.decide("yes");
  await settle();

  ctx.undo();
  assert.ok(ctx.state.updatedAt > stale,
    "an undo is itself a write — a snapshot's old timestamp would lose the next cloud reconcile");
});

