  const lines=[],g={save(){},restore(){},translate(){},rotate(){},scale(){},beginPath(){},roundRect(){},fill(){},fillRect(){}};
  const geometry={lowerRail:x=>500+Math.sin(x/80)*4,tangent:()=>0};
