test('RISK landscape banners: the longest human airplane prompt fits measured fabric in both directions',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 const markdown=fs.readFileSync(path.join(__dirname,'HUMAN_WRITTEN_HOURLY_TAGS.md'),'utf8');
 const airplaneSection=markdown.split(/^## Airplanes\s*$/m)[1]?.split(/^## /m)[0]||'';
 const configured=[...airplaneSection.matchAll(/^\s*-\s+(.+)\s*$/gm)].map(match=>match[1]);
 const stressPrompt='Remember that taking a moment to look around can turn an ordinary flight into a peaceful reminder that there is time to breathe';
 const prompt=(configured.length?configured:[stressPrompt]).sort((a,b)=>b.length-a.length)[0];
 const mood=moodRuntime();mood.setHumanText(`## Airplanes\n- ${prompt}`);
 assert.equal(mood.airplaneMessage(()=>0),prompt,'the layout uses the same editable human airplane-message path as the renderer');
 const source=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8');
 assert.ok(source.includes('geometry.bannerLayout('),'the painter consumes the measured banner geometry');
 assert.ok(source.includes('g.measureText('),'fabric width uses the active canvas font metrics');
 for(const [width,height] of [[320,568],[568,320],[768,1024],[1440,900]]){
  const scene=ctx.LandscapeGeometry.create(width,height),maxWidth=Math.min(144,width*.44);
  const measure=(line,fontSize)=>Array.from(line).reduce((sum,letter)=>sum+fontSize*(letter===' '?0.28:/[il.,'!]/.test(letter)?0.27:/[MW]/.test(letter)?0.82:0.57),0);
  for(const direction of [-1,1]){
   const layout=scene.bannerLayout(prompt,width/2,40,direction,measure);
   assert.equal(layout.direction,direction);
   assert.ok(layout.lines.length>1,'long human copy wraps instead of running past the fabric');
   assert.equal(layout.lines.join(' '),prompt,'wrapping preserves every character and word');
   assert.ok(layout.width<=maxWidth,`${width}x${height}: fabric stays within the viewport allowance`);
   assert.ok(layout.fontSize>=6,`${width}x${height}: wrapped copy remains legible`);
   for(const line of layout.lines)assert.ok(measure(line,layout.fontSize)<=layout.width-8,`${width}x${height}: measured line fits inside fabric padding`);
   assert.ok(layout.height>=layout.lines.length*layout.fontSize*1.2+4,'fabric height contains every measured text row');
   assert.equal(layout.towEndX,layout.x+direction*layout.width/2,'tow line meets the near edge for forward and reverse travel');
   assert.equal(layout.towStartX,width/2-direction*18,'tow line begins at the biplane tail in either direction');
  }
 }
});

test('RISK skyline lights: garden roofs start independently, stay stable, and change slowly at night',()=>{
 const sky=livingSky(),context=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),context);
 const seed=value=>{const v=Math.sin(value*127.1+311.7)*43758.5453;return v-Math.floor(v);};
 for(const [width,height] of [[320,568],[568,320],[768,1024],[1440,900]]){
  const gardens=context.LandscapeGeometry.create(width,height).cityscape(seed).gardens.map(garden=>garden.index);
  assert.ok(gardens.length>0,`${width}x${height}: eligible planted roofs exist`);
  let draws=0;const alternating=sky.createGardenLights(gardens,()=>draws++%2===0?.99:.01);
  assert.equal(draws,gardens.length,`${width}x${height}: each eligible roof receives an independent initial draw`);
  assert.ok(gardens.some(index=>alternating.lit[index])&&gardens.some(index=>!alternating.lit[index]),`${width}x${height}: roofs can have different light states together`);
  const before={...alternating.lit};
  sky.syncGardenLights(alternating,gardens,()=>{throw new Error('unchanged roofs must not be rerolled during paint');});
  assert.deepEqual(JSON.parse(JSON.stringify(alternating.lit)),before,'repainting the same plan keeps every roof state stable');
 }
 const ids=[1,2,3,4],allOn=sky.createGardenLights(ids,()=>0),allOff=sky.createGardenLights(ids,()=>.99);
 assert.ok(ids.every(index=>allOn.lit[index]),'independent outcomes allow all eligible garden roofs to be lit');
 assert.ok(ids.every(index=>!allOff.lit[index]),'independent outcomes allow every garden roof to be dark');
 const state=sky.createGardenLights(ids,()=>.99),initial={...state.lit},samples=[0,.99,0,0];
 const random=()=>samples.shift()??.99;
 assert.equal(sky.advanceGardenLights(state,59,true,()=>0),false,'garden lights remain steady between scheduled changes');
 assert.deepEqual(JSON.parse(JSON.stringify(state.lit)),initial);
 assert.equal(sky.advanceGardenLights(state,1,true,random),false,'a resample that remains dark does not request a repaint');
 assert.deepEqual(JSON.parse(JSON.stringify(state.lit)),initial,'the selected roof retains its sampled state when the next outcome matches');
 assert.equal(sky.advanceGardenLights(state,60,true,random),true,'a later one-in-twelve resample can light one roof');
 assert.equal(ids.filter(index=>state.lit[index]!==initial[index]).length,1);
 const day=sky.createGardenLights(ids,()=>.99),dayState={...day.lit};
 assert.equal(sky.advanceGardenLights(day,300,false,()=>0),false,'daylight never switches garden lights');
 assert.deepEqual(JSON.parse(JSON.stringify(day.lit)),dayState);
 const source=fs.readFileSync(path.join(__dirname,'landscape.js'),'utf8'),background=source.slice(source.indexOf('  function paintBackground(){'),source.indexOf('  function paintWoodland('));
 assert.match(background,/gardenLights\.lit\[garden\.index\]/,'only the selected roof states control visible garden fixtures');
 assert.ok(source.includes('syncScene(Date.now())'),'normal motion reads the shared UTC light state');
 assert.ok(source.includes('cityLights.gardens.lit[roof.index]=sceneSnapshot.gardens[nearest]??false'),'both motion modes adopt the same normalized roof samples');
 assert.ok(source.includes('else partyTimer=setInterval(()=>advanceRooftopParty(1),1000)'),'reduced motion uses its visible-time timer instead of animated frames');
});

test('RISK Landscape browser: both night shows reflect actual sparks and exposed windows visibly switch on and off', {skip:!process.env.LANDSCAPE_BROWSER_URL},async()=>{
 const {chromium}=await import(process.env.LANDSCAPE_PLAYWRIGHT);
 const browser=await chromium.launch({headless:true,channel:process.env.LANDSCAPE_BROWSER_CHANNEL||'chrome'});
 try{for(const [width,height] of [[320,568],[568,320],[768,1024],[1440,900]]){
  const page=await browser.newPage({viewport:{width,height},deviceScaleFactor:1,serviceWorkers:'block'}),errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.clock.setFixedTime(new Date('2026-09-30T03:00:00Z'));
  await page.addInitScript(()=>localStorage.setItem('fvp:chain-scanner:landscape-motion','reduced'));
  await page.route('**/landscape.js',async route=>{
   const response=await route.fetch();let body=await response.text();
   body=body.replace('resize();updateMotion();if(preference===null)openMotion();',`resize();updateMotion();if(preference===null)openMotion();
    globalThis.nightShowProbe=()=>{
     stop();reduced=false;world.events=[];paintBackground();
     const read=()=>new Uint8ClampedArray(g.getImageData(0,0,W,H).data),shows=[];
     for(const type of ['fireworks','festival']){
      world.events=[{type,age:type==='festival'?78.2:1.6,duration:type==='festival'?150:9,seed:.4,lane:.4,reverse:false}];
      const shells=geometry.fireworks;geometry.fireworks=()=>[];paintLife(20);const without=read();geometry.fireworks=shells;paintLife(20);const withSparks=read();let pixels=0;
      for(let x=0;x<W;x++)for(let y=Math.ceil(geometry.waterTop+2);y<Math.min(H,geometry.far(x)-2);y++){
       const j=(y*W+x)*4;if(Math.abs(withSparks[j]-without[j])+Math.abs(withSparks[j+1]-without[j+1])+Math.abs(withSparks[j+2]-without[j+2])>6)pixels++;
      }
      shows.push({type,pixels});
     }
     const selected=cityLights.visible?.[0],count=Math.ceil(W/15);let index=0,patch,windowKey;
     for(let i=0;i<count;i++){
      const x=i*W/count,cluster=.4+.6*Math.pow(Math.sin(x/W*Math.PI*3+.5),2),bh=(18+rand(i+14)*65)*cluster*(W<600?.8:1),bw=7+rand(i+91)*18,y=hy+12-bh;
      for(let yy=y+5;yy<hy+8;yy+=7)for(let xx=x+3;xx<x+bw-2;xx+=5)if(index++===selected){patch=[Math.floor(xx),Math.floor(yy),3,4];windowKey=\`${'${'}Math.round(i/count*96)}:${'${'}Math.round((xx-x-3)/5)}:${'${'}Math.round((yy-y-5)/7)}\`;}
     }
     if(!patch)return {shows,lights:null};
     const readPatch=()=>Array.from(base.getImageData(...patch).data),difference=(a,b)=>a.reduce((n,v,i)=>n+Math.abs(v-b[i]),0);
     const originalSlot=sceneSnapshot.windowsSlot,slots=[originalSlot],initial=T.windowLit(sceneSeed,windowKey,originalSlot);
     for(let slot=originalSlot+1;slot<originalSlot+20000&&slots.length<3;slot++){
      const expected=slots.length===1?!initial:initial;
      if(T.windowLit(sceneSeed,windowKey,slot)===expected)slots.push(slot);
     }
     sceneSnapshot.windowsSlot=slots[0];paintBackground();const before=readPatch();
     sceneSnapshot.windowsSlot=slots[1];paintBackground();const after=readPatch();
     sceneSnapshot.windowsSlot=slots[2];paintBackground();const restored=readPatch();sceneSnapshot.windowsSlot=originalSlot;
     return {shows,lights:{changed:difference(before,after),returned:difference(before,restored)}};
    };`);
   await route.fulfill({response,body});
  });
  await page.goto(process.env.LANDSCAPE_BROWSER_URL,{waitUntil:'networkidle'});await page.waitForFunction(()=>window.nightShowProbe);
  const probe=await page.evaluate(()=>nightShowProbe());
  for(const show of probe.shows)assert.ok(show.pixels>8,`${width}x${height} ${show.type}: individual sparks must reach visible water, not just the stage`);
  assert.ok(probe.lights&&probe.lights.changed>50,'a selected exposed window visibly switches');
  assert.ok(probe.lights.returned<probe.lights.changed*.08+30,'the next switch restores the original window color within canvas rounding');
  assert.deepEqual(errors,[]);await page.close();
 }}finally{await browser.close();}
});


test('RISK festival barge: shell launches follow the moving deck and fireworks have varied ballistic trails',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 for(const [w,h] of [[320,568],[568,320],[1440,900]])for(const reverse of [false,true]){
  const g=ctx.LandscapeGeometry.create(w,h),e={type:'festival',duration:150,seed:.4,reverse};
  const p=g.festival({...e,age:50}),q=g.festival({...e,age:60}),r=g.festival({...e,age:70});
  assert.ok(Math.abs((q.x-p.x)-(r.x-q.x))<1e-6,'barge has constant horizontal travel speed');
  assert.equal(Math.sign(q.x-p.x),reverse?-1:1,'barge actually moves in its chosen direction');
  assert.equal(g.waterDepth({...e,age:60},60),q.y,'barge participates in physical water depth ordering');
  for(const launch of [42.2,49.8]){
   const age=launch+.12,deck=g.festival({...e,age});
   const rocket=g.fireworks(age,.4,true,e).find(dot=>dot.kind==='rocket');
   assert.ok(rocket,'a shell rises while its deck is on screen');
   assert.ok(Math.abs(rocket.x-deck.x)<deck.width*.65,'launch stays attached to the traveling deck');
  }
 }
});

test('RISK fireworks realism: uneven blooms leave ballistic trails and fading embers',()=>{
 const ctx=vm.createContext({Math});vm.runInContext(fs.readFileSync(path.join(__dirname,'landscape-geometry.js'),'utf8'),ctx);
 const g=ctx.LandscapeGeometry.create(1440,900),sparks=g.fireworks(1.8,.4).filter(dot=>dot.kind==='spark');
 assert.ok(sparks.length>=30,'fuller bursts use multiple spark lengths');
 const cx=sparks.reduce((n,d)=>n+d.x,0)/sparks.length,cy=sparks.reduce((n,d)=>n+d.y,0)/sparks.length;
 const radii=sparks.map(d=>Math.hypot(d.x-cx,d.y-cy));
 assert.ok(Math.max(...radii)-Math.min(...radii)>Math.max(...radii)*.3,'sparks fill the bloom instead of making a tidy ring');
 for(const spark of sparks){assert.ok(spark.trail.length>=4);for(const point of spark.trail)for(const value of [point.x,point.y,point.alpha])assert.ok(Number.isFinite(value));}
 const late=g.fireworks(3.1,.4).filter(dot=>dot.kind==='spark');
 assert.ok(late.some(d=>d.trail.at(-1).y>d.trail[0].y),'gravity curves trails down as embers fade');
});


